const norm = (s) => s.toLowerCase().replace(/\.net/g, "dotnet").replace(/[^a-z0-9]+/g, "-");

export function getDevelopersByPath(path = "") {
  const p = "-" + norm(path) + "-";
  const pairs = Object.entries(ALIASES)
    .flatMap(([tech, list]) => list.map((a) => [tech, a]))
    .sort((a, b) => b[1].length - a[1].length);
  for (const [tech, a] of pairs) {
    if (p.includes("-" + a + "-")) return DEVELOPERS[tech];
  }
  return null;
}
